#!/usr/bin/env python3
"""Assembles REPLAY-FIXES-REPORT.md from the replay outputs of the listed sessions.

Usage: .venv/bin/python -I analysis/replay-report.py sessions/<id> [sessions/<id> ...]

Inputs per session: replay-none.json, replay-fidelity-none.json, replay-compare.json, optional replay-strips.json and
replay-none-repeat.jsonl (a second `none` run, for replay-vs-replay repeatability). Writes gaze-lab/REPLAY-FIXES-REPORT.md.
"""
import json
import math
import sys
from pathlib import Path

import numpy as np

LAB = Path(__file__).resolve().parent.parent
GROUPS = [("translation B2/B3/B5/B6/B7", ["B2", "B3", "B5", "B6", "B7"]), ("pitch B10/B11/B13", ["B10", "B11", "B13"]), ("yaw B8/B9", ["B8", "B9"]), ("neutral B1/B12", ["B1", "B12"]), ("up B4", ["B4"])]


def finite2(p):
    return isinstance(p, (list, tuple)) and len(p) == 2 and all(isinstance(v, (int, float)) and math.isfinite(v) for v in p)


def per_dot(rows, w, h, field, blocks):
    out = {}
    for r in rows:
        if r["screen"] == "block" and r["phase"] == "record" and r["facePresent"] and r["eyeState"] == "open" and r.get("target") and r["block"] in blocks and finite2(r[field]):
            out.setdefault((r["block"], r["point"]), []).append(((r[field][0] + .5) * w, (r[field][1] + .5) * h, r["target"]["x"], r["target"]["y"]))
    res = {}
    for k, lst in out.items():
        a = np.array(lst); m = np.median(a[:, :2], axis=0)
        res[k] = (m, math.hypot(m[0] - a[0, 2], m[1] - a[0, 3]))
    return res


def verdict(p):
    lo, hi = p["ci95"]
    if hi < 0:
        return "helps"
    if lo > 0:
        return "hurts"
    return "no call"


def main(folders):
    L = ["# Replay of the two candidate fixes on the recorded live sessions", "",
         "Generated by `analysis/replay-report.py` from `scripts/replay-blocks.mjs` outputs (2026-11-07). One tester (Abdelrahman), two sessions, shipped pipeline at Clarte `b7b8f98`. px = CSS px of the 1512×949 viewport (0.0200 cm/px). Negative paired differences = the variant is better. Nothing here is proven beyond this one tester; see Limits.", ""]
    L += ["## 1. Fidelity gate: does the `none` replay reproduce the live run?", "",
          "The replay steps, for every live `frames.jsonl` row, the decoded `video.webm` frame nearest to the live video time (clock offset measured per session by matching the 478 landmarks of 60 sampled rows); the 42 recorded labels are collected on their recorded frames and `train` runs at the recorded moment. Fidelity is checked on the 42 labelled calibration frames (pretrained network, no training involved) and on the record-phase frames of every block (after training).", ""]
    L += ["| session | clock offset | labels collected | landmarks mean \\|Δ\\| (norm. units ≈ px @1280) | headVector max\\|Δ\\| median | faceOrigin3D \\|Δ\\| median (cm) | pretrained network \\|Δ\\| on label frames: median / p90 / max px | training heldOutBefore replay vs live | heldOutAfter replay vs live | bestStep | geometric heldOutMse replay vs live |", "|---|---|---|---|---|---|---|---|---|---|---|"]
    fid_rows, strip_rows, repeat_rows = [], [], []
    for folder in folders:
        f = Path(folder)
        none = json.loads((f / "replay-none.json").read_text()); tr = none["trainingReport"]; fl = none["fidelity"]["labelFrames"]; fr = none["fidelity"]["recordFrames"]
        sid = none["session"].split("-")[-1]
        L.append(f"| Test-{sid[-1]} | {none['offsetMs']} ms | {none['counts']['collected']}/42 ({none['counts']['shifted']} shifted, {none['counts']['missed']} missed) | {fr['landmarkMeanAbsDelta']['median']:.2e} (≈ {fr['landmarkMeanAbsDelta']['median'] * 1280:.2f} px) | {fr['headVector_maxAbs']['median']:.4f} | {fr['faceOrigin3D_cm_maxAbs']['median']:.3f} | {fl['network_px']['median']:.1f} / {fl['network_px']['p90']:.1f} / {fl['network_px']['max']:.1f} | {tr['replay']['heldOutBefore']:.6f} vs {tr['live']['heldOutBefore']:.6f} | {tr['replay']['heldOutAfter']:.6f} vs {tr['live']['heldOutAfter']:.6f} | {tr['replay']['bestStep']} vs {tr['live']['bestStep']} | {tr['replay']['geometric']['heldOutMse']:.6f} vs {tr['live']['geometric']['heldOutMse']:.6f} |")
        fid = json.loads((f / "replay-fidelity-none.json").read_text())
        for s in ("blend", "network", "geometric"):
            o = fid["overall"][s]
            fid_rows.append(f"| Test-{sid[-1]} | {s} | {o['blocks']} | {o['block_median_abs_delta_median']:.0f} / {o['block_median_abs_delta_max']:.0f} | {o['per_dot_abs_err_delta']['median']:.0f} / {o['per_dot_abs_err_delta']['p90']:.0f} / {o['per_dot_abs_err_delta']['max']:.0f} | {o['per_dot_distance']['median']:.0f} / {o['per_dot_distance']['p90']:.0f} | {o['frame_delta']['median']:.0f} / {o['frame_delta']['p90']:.0f} | {o['live_consecutive_delta_median']:.0f} |")
        if (f / "replay-strips.json").exists():
            st = json.loads((f / "replay-strips.json").read_text())
            strip_rows.append(f"| Test-{sid[-1]} | {st['compared']}/{st['labels']} | {st['stripMeanAbs']['median']:.2f} (max {st['stripMeanAbs']['max']:.2f}) | {st['psnr']['median']:.1f} (min {st['psnr']['min']:.1f}) | " + (f"{' / '.join(f'{v:+.2f}' for v in st['signedMeanRGB'])}" if 'signedMeanRGB' in st else '—') + f" | {st['landmarkMeanAbsDelta']['median'] * 1280:.2f} px | {st['networkDeltaPx']['median']:.1f} / {st['networkDeltaPx']['p90']:.1f} / {st['networkDeltaPx']['max']:.1f} |")
        if (f / "replay-none-repeat.jsonl").exists():
            session = json.loads((f / "session.json").read_text()); w, h = session["viewport"]["width"], session["viewport"]["height"]
            blocks = {b["key"] for b in session["blocks"] if b["status"] == "complete"}
            a = [json.loads(l) for l in (f / "replay-none.jsonl").read_text().splitlines() if l.strip()]
            b = [json.loads(l) for l in (f / "replay-none-repeat.jsonl").read_text().splitlines() if l.strip()]
            rep = json.loads((f / "replay-none-repeat.json").read_text())["trainingReport"]["replay"]
            for s, field in (("blend", "rawNormPog"), ("network", "network")):
                pa, pb = per_dot(a, w, h, field, blocks), per_dot(b, w, h, field, blocks)
                keys = [k for k in pa if k in pb]
                derr = [abs(pa[k][1] - pb[k][1]) for k in keys]; dist = [math.hypot(*(pa[k][0] - pb[k][0])) for k in keys]
                fa = {r["i"]: r for r in a}; fd = [math.hypot((r[field][0] - fa[r["i"]][field][0]) * w, (r[field][1] - fa[r["i"]][field][1]) * h) for r in b if r["i"] in fa and finite2(r[field]) and finite2(fa[r["i"]][field]) and r["phase"] == "record"]
                repeat_rows.append(f"| Test-{sid[-1]} | {s} | {len(keys)} | {np.median(derr):.0f} / {np.percentile(derr, 90):.0f} / {np.max(derr):.0f} | {np.median(dist):.0f} / {np.max(dist):.0f} | {np.median(fd):.0f} / {np.percentile(fd, 90):.0f} | {tr['replay']['heldOutBefore']:.6f} vs {rep['heldOutBefore']:.6f}; after {tr['replay']['heldOutAfter']:.6f} vs {rep['heldOutAfter']:.6f}; bestStep {tr['replay']['bestStep']} vs {rep['bestStep']} |")
    L += ["", "Per block, per dot and per frame (`analysis/replay-fidelity.py`, record-phase frames usable in both runs):", "",
          "| session | stream | blocks | per-block median px \\|replay − live\\|: median / max | per-dot error \\|Δ\\| median / p90 / max | per-dot estimate distance median / p90 | same-frame \\|Δ\\| median / p90 | live consecutive-frame \\|Δ\\| median (noise reference) |", "|---|---|---|---|---|---|---|---|"] + fid_rows
    if strip_rows:
        L += ["", "Eye strips on the labelled calibration frames (`scripts/replay-strips.mjs`: the worker's 512×128 strip from the re-decoded frame vs the lossless strip the live worker kept of the same frame):", "",
              "| session | strips | mean \\|Δ\\| per RGB value (of 255) | PSNR dB | signed mean Δ R / G / B | landmarks \\|Δ\\| | pretrained network \\|Δ\\| median / p90 / max px |", "|---|---|---|---|---|---|---|"] + strip_rows
    if repeat_rows:
        L += ["", "Replay-vs-replay repeatability (a second `none` run on the same machine, same frames):", "",
              "| session | stream | dots | per-dot error \\|Δ\\| median / p90 / max | per-dot estimate distance median / max | same-frame \\|Δ\\| median / p90 | training report run 1 vs run 2 |", "|---|---|---|---|---|---|---|"] + repeat_rows
    L += ["", "**Verdict on the gate.** The gate as specified (per-block medians within a few px, per-dot medians within ~10 px) is **not met**: per-block blend medians differ from the live run by a median 14-18 px (max 31-48 px), per-dot blend errors by a median 23-32 px. What was ruled out: frame alignment and missing frames (every live row got a frame, labels all collected on their recorded frames, landmarks match to ~0.3 px, head vector to 2e-3, face origin to 0.1-0.9 cm, face/eye state identical on every frame), and training nondeterminism (`rerun_head.mjs` F3: a re-run of `adapt()` on the *lossless* live strips moves the calibration-frame predictions by at most 8 px; the repeat run above bounds replay-vs-replay noise). What remains is the pixel content: the eye strips cut from the 5 Mbps VP9 recording differ from the live strips by ~4 of 255 per value (PSNR ~28 dB), and the pretrained network alone moves by a median 45 px on those frames before any training; training on 42 such strips then lands on a different head (heldOutBefore 0.0016 vs 0.0024 and 0.0082 vs 0.0100). The replay is therefore a faithful *geometry* replay but not a pixel-exact one, and every variant number below is read only as a paired difference against the `none` replay, which saw identical frames, strips and labels (the compare script verifies identical stepped frames and face/eye states per variant).", ""]
    # 2. per-session tables
    for folder in folders:
        f = Path(folder); cmp = json.loads((f / "replay-compare.json").read_text()); sid = cmp["session"].split("-")[-1]
        session = json.loads((f / "session.json").read_text()); titles = {b["id"]: b["title"] for b in session["blocks"]}
        variants = cmp["variants"]; others = [v for v in variants if v != "none"]
        L += [f"## 2.{folders.index(folder) + 1} Test-{sid[-1]} · {cmp['session']} · {len(cmp['blocks'])} blocks", "",
              f"Training reports (replay): " + "; ".join(f"{v}: heldOut {cmp['training'][v]['heldOutBefore']:.5f} → {cmp['training'][v]['heldOutAfter']:.5f}, bestStep {cmp['training'][v]['bestStep']}, blend weight {cmp['training'][v]['geometric']['weight']:.2f}" for v in variants) + ".", ""]
        for s in ("blend", "network"):
            L += [f"### {s}: per-dot median error (px) per block and paired difference vs none (mean over dots, 95 % bootstrap)", "",
                  "| block | dots | " + " | ".join(variants) + " | " + " | ".join(f"Δ {v}" for v in others) + " | " + " | ".join(f"{v}" for v in others) + " |", "|---|---|" + "---|" * (len(variants) + 2 * len(others))]
            for bid, b in cmp["blocks"].items():
                e = b[s]
                L.append(f"| {bid} {titles[bid]} | {e['dots']} | " + " | ".join(f"{e['median_error_px'][v]:.0f}" for v in variants) + " | " + " | ".join(f"{p['mean_diff_px']:+.0f} [{p['ci95'][0]:+.0f}, {p['ci95'][1]:+.0f}] ({p['dots_better']}/{p['n']})" for v, p in e["paired"].items()) + " | " + " | ".join(verdict(p) for p in e["paired"].values()) + " |")
            po = cmp["pooled"][s]
            L.append(f"| **all blocks** | {po[others[0]]['n']} | | | | | " + " | ".join(f"{p['mean_diff_px']:+.0f} [{p['ci95'][0]:+.0f}, {p['ci95'][1]:+.0f}] ({p['dots_better']}/{p['n']})" for p in po.values()) + " | " + " | ".join(verdict(p) for p in po.values()) + " |")
            L += ["", f"Block groups ({s}, mean paired Δ px [95 %], dots better/n):", "", "| group | blocks present | " + " | ".join(f"Δ {v}" for v in others) + " |", "|---|---|" + "---|" * len(others)]
            for gname, g in cmp["groups"][s].items():
                L.append(f"| {gname} | {' '.join(g['blocks'])} | " + " | ".join(f"{g[v]['mean_diff_px']:+.0f} [{g[v]['ci95'][0]:+.0f}, {g[v]['ci95'][1]:+.0f}] ({g[v]['dots_better']}/{g[v]['n']}) · {verdict(g[v])}" for v in others) + " |")
            L.append("")
        geo = cmp["pooled"]["geometric"]
        L += [f"Geometric control (should not move): pooled Δ " + "; ".join(f"{v} {p['mean_diff_px']:+.1f} px [{p['ci95'][0]:+.1f}, {p['ci95'][1]:+.1f}]" for v, p in geo.items()) + ".", "", f"Figure: `{f.name}/replay-compare.png`.", ""]
    # 3. summary per fix and limits
    L += ["## 3. Which blocks each fix helps or hurts (blend = what the app uses; per-block verdict = the 95 % interval of the paired per-dot difference excludes 0)", ""]
    for folder in folders:
        f = Path(folder); cmp = json.loads((f / "replay-compare.json").read_text()); sid = cmp["session"].split("-")[-1]
        for v in [x for x in cmp["variants"] if x != "none"]:
            helps = [b for b, e in cmp["blocks"].items() if verdict(e["blend"]["paired"][v]) == "helps"]
            hurts = [b for b, e in cmp["blocks"].items() if verdict(e["blend"]["paired"][v]) == "hurts"]
            po = cmp["pooled"]["blend"][v]
            L.append(f"- **Test-{sid[-1]} · {v}** (blend): helps {', '.join(helps) or 'none'}; hurts {', '.join(hurts) or 'none'}; pooled {po['mean_diff_px']:+.0f} px [{po['ci95'][0]:+.0f}, {po['ci95'][1]:+.0f}], {po['dots_better']}/{po['n']} dots better. Network alone: pooled {cmp['pooled']['network'][v]['mean_diff_px']:+.0f} px [{cmp['pooled']['network'][v]['ci95'][0]:+.0f}, {cmp['pooled']['network'][v]['ci95'][1]:+.0f}].")
    L += ["", "### Reading", "",
          "- **freezePose** is the only variant that never hurts the pooled blend and the only one with a large, interval-clear gain: Test-2 B2/B3 network 959 → 107 and 857 → 109 px (blend 667 → 239, 563 → 217), B6 and B13 also better, pooled blend −127 px [−161, −92]. On Test-1 it is a null: pooled −0.3 px [−1.9, +1.3], per-block effects within ±20 px. The two sessions differ in what the baseline training did: the Test-1 `none` replay stopped at bestStep 80 with the network already at the level the offline frozen re-run reached on the live strips (`rerun_head.md`: shipped head B2 190 / B5 201 / B13 131 px, frozen 109 / 106 / 84; replay `none` 103 / 100 / 62), so there was little pose-row drift left to prevent; the live Test-1 training (bestStep 150, 200 steps) and the Test-2 trainings drifted. The freeze fix therefore removes a failure mode that depends on the training trajectory; it is a safety property, not a constant gain.",
          "- **matrixLayout** alone hurts on both sessions (pooled blend +14 px [+5, +23] and +21 px [+10, +32]); it hurts the translation and yaw groups (Test-1 B2 +131, B5 +60, B9 +54; Test-2 B2 +137) and helps B6 (−50) on Test-1 and B3 (−34) on Test-2. The pretrained head reacts to the corrected (sign-flipped) head vector and the 42 one-pose labels cannot re-fit that response; the geometric branch is untouched (control exactly 0).",
          "- **both** behaves like layout where layout hurts (B2, B5, B9 on Test-1) and like freeze where freeze helps (Test-2: pooled −120 px [−153, −89]); on Test-1 it is a wash (+0.3 px [−6, +7]). Freezing the pose rows does not neutralize the layout change because the frozen rows are exactly the ones that read the flipped vector.",
          "- Order of the fixes on this evidence: ship `freezePose` (never worse than the baseline by more than the interval width, large gain when the baseline drifts); do not ship `matrixLayout` on its own, and ship it together with a head retrained or re-adapted on the corrected convention rather than with the current pretrained head.", ""]
    L += ["", "## 4. Limits", "",
          "- One tester, two sessions, one laptop and camera; the second session ran at ~10 fps with a shadow worker and calibrated much worse than the first (live heldOutAfter 0.0062 vs 0.0007), so its B2/B3 baselines are extreme. Nothing generalizes beyond that without other people.",
          "- The replay is not pixel-exact (section 1): 5 Mbps VP9 recompression moves the pretrained network by a median ~45 px per frame and the trained head differs from the live one. Variant effects are paired against the `none` replay on identical frames; absolute px values are replay values, not live ones. Effects smaller than the replay-vs-replay repeatability above are not interpretable.",
          "- Per-dot medians over ~15 record frames are the unit; bootstrap intervals are over 15-16 dots per block (111-207 pooled), which is why per-block intervals are wide.",
          "- The face origin is reconstructed from a face width estimated on the first frame with a face; the replay's first frame is not the live one (the live run started before the recording), so faceOrigin3D carries a constant depth scale offset of ~0.2-2 % per session. It enters both the network input and the geometric depth feature identically in every variant.",
          "- `freezePose` keeps the pretrained pose rows; it does not add pose compensation that the pretrained head lacks. `matrixLayout` only changes the head vector the network sees (the face origin is unchanged to 1e-3 cm); its sign flip interacts with a head that was pretrained on the Python convention, and on these sessions that interaction is measured, not modelled.",
          "- Saved calibrations and team models must be invalidated (MODEL_VERSION bump) if `matrixLayout` ships; the patch header says so.", ""]
    (LAB / "REPLAY-FIXES-REPORT.md").write_text("\n".join(L) + "\n")
    print(f"wrote {LAB / 'REPLAY-FIXES-REPORT.md'} ({len(L)} lines)")


if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit(__doc__)
    main(sys.argv[1:])
